import re
from dataclasses import dataclass
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

KEYS = ("max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days")

_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_WHOLE = re.compile(r"[0-9]+\Z")
_STREAM_HEADER = re.compile(r"stream (.*)\Z")

_UNITS = {"": 1, "k": 1024, "m": 1024 * 1024, "g": 1024 * 1024 * 1024}
_MINUTES = {"m": 1, "h": 60, "d": 24 * 60}


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None  # bytes; None is off
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timedelta = timedelta(0)
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


class _Invalid(Exception):
    pass


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        raise _Invalid(v)
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    if v == "off":
        return None
    m = _DURATION.match(v)
    if not m:
        raise _Invalid(v)
    return timedelta(minutes=int(m.group(1)) * _MINUTES[m.group(2)])


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _Invalid(v)
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _Invalid(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -delta if m.group(1) == "-" else delta


def _whole(minimum):
    def parse(v):
        if not _WHOLE.match(v) or int(v) < minimum:
            raise _Invalid(v)
        return int(v)

    return parse


def _keep_days(v):
    if v == "off":
        return None
    return _whole(1)(v)


_PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _whole(0),
    "keep": _whole(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def stream_names(self):
        return set(self.sections)

    def settings(self, name: str) -> Settings:
        merged = dict(self.defaults)
        merged.update(self.sections.get(name, {}))
        return Settings(**merged)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    return parse(text, path.name)


def parse(text: str, label: str = "policy.ini") -> Policy:
    def bad(why):
        return DataError("policy", f"{label}: {why}")

    defaults: dict = {}
    sections: dict = {}
    seen_defaults = False
    current = None
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if line[-1] != "]":
                raise bad(f"line {number}: bad section header")
            title = line[1:-1]
            if title == "defaults":
                if seen_defaults:
                    raise bad(f"line {number}: [defaults] given twice")
                seen_defaults = True
                current = defaults
                continue
            m = _STREAM_HEADER.match(title)
            if not m or not streams.valid(m.group(1)):
                raise bad(f"line {number}: unknown section")
            if m.group(1) in sections:
                raise bad(f"line {number}: section given twice")
            current = sections[m.group(1)] = {}
            continue
        if current is None or "=" not in line:
            raise bad(f"line {number}: not a setting")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in _PARSERS:
            raise bad(f"line {number}: unknown key {key}")
        if key in current:
            raise bad(f"line {number}: {key} given twice")
        try:
            current[key] = _PARSERS[key](value)
        except _Invalid:
            raise bad(f"line {number}: bad value for {key}") from None
    return Policy(defaults, sections)
"}

