import gzip
import os
import re
from dataclasses import dataclass
from datetime import date, timedelta, timezone
from pathlib import Path

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused


@dataclass
class Archive:
    name: str  # file name before the run; "" for the new archive
    gz: bool
    key: tuple  # place in the age order; larger is newer for dated, smaller for numbered
    day: str = ""
    k: int = 1
    time: str | None = None  # the time as stored in state.json (or written)
    new: bool = False
    final: str = ""
    compress: bool = False
    content: bytes | None = None


def _day_ok(text: str) -> bool:
    try:
        date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return False
    return True


def _scan(data: Path, name: str, naming: str) -> list[Archive]:
    """The archives of a stream, newest first."""
    d = streams.logs_dir(data)
    if naming == "numbered":
        rx = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?")
    else:
        rx = re.compile(re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")
    found = []
    places = {}
    if d.is_dir():
        for p in d.iterdir():
            m = rx.fullmatch(p.name)
            if not m or not p.is_file():
                continue
            if naming == "numbered":
                a = Archive(p.name, m.group(2) is not None, (int(m.group(1)),))
                place = a.key
            else:
                if not _day_ok(m.group(1)):
                    continue
                k = int(m.group(2)) if m.group(2) else 1
                a = Archive(p.name, m.group(3) is not None, (m.group(1), k), day=m.group(1), k=k)
                place = a.key
            if place in places:
                raise DataError("archives", f"{name}: two archives in the same place: {places[place]} and {p.name}")
            places[place] = p.name
            found.append(a)
    if naming == "numbered":
        found.sort(key=lambda a: a.key)
    else:
        found.sort(key=lambda a: a.key, reverse=True)
    return found


def _validate_state(doc: dict, existing: set) -> None:
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        if "opened" in entry and dates.parse_state(entry["opened"]) is None:
            raise DataError("state", f"{name}: opened is not a time")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for fname, t in arch.items():
                if dates.parse_state(t) is None:
                    raise DataError("state", f"{name}: time of {fname} is not a time")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: rotations is not a whole number")


def _first_line_time(path: Path):
    try:
        with path.open("rb") as f:
            line = f.readline(4096)
    except OSError:
        return None
    line = line.split(b"\n", 1)[0].rstrip(b"\r")
    token = line.split(b" ", 1)[0].decode("utf-8", errors="replace")
    return dates.parse_aware(token)


def _decide(ctx, name: str, st: policy_mod.Settings, entry: dict, force: bool) -> tuple[bool, str]:
    log = streams.log_path(ctx.data, name)
    if not log.is_file():
        return False, "no log"
    size = log.stat().st_size
    if size == 0:
        return False, "empty"
    if force:
        return True, "forced"
    if st.max_size is not None and size >= st.max_size:
        return True, "size"
    if st.max_age is not None:
        opened = dates.parse_state(entry["opened"]) if "opened" in entry else _first_line_time(log)
        if opened is not None and ctx.now - opened >= st.max_age:
            return True, "age"
    return False, "not due"


def _plan(ctx, name, st, entry, existing_archives, rotated):
    items = list(existing_archives)
    arch_times = entry.get("archives", {})
    for a in items:
        a.time = arch_times.get(a.name)
    if rotated:
        stamp = dates.stamp(ctx.now)
        if st.naming == "numbered":
            items.insert(0, Archive("", False, (0,), time=stamp, new=True))
        else:
            local = ctx.now.astimezone(timezone(st.offset)).date().isoformat()
            same = [a for a in items if a.day == local]
            k = max(a.k for a in same) + 1 if same else 1
            new = Archive("", False, (local, k), day=local, k=k, time=stamp, new=True)
            items.append(new)
            items.sort(key=lambda a: a.key, reverse=True)
    kept, removed = [], []
    for pos, a in enumerate(items, 1):
        gone = pos > st.keep
        if not gone and st.keep_days is not None and a.time is not None:
            t = dates.parse_state(a.time)
            gone = ctx.now - t >= timedelta(days=st.keep_days)
        (removed if gone else kept).append(a)
    for j, a in enumerate(kept, 1):
        a.compress = j > st.compress_after and not a.gz
        gz = a.gz or a.compress
        if st.naming == "numbered":
            base = f"{name}.log.{j}"
        else:
            base = f"{name}.log.{a.day}" + (f".{a.k}" if a.k > 1 else "")
        a.final = base + (".gz" if gz else "")
    return kept, removed


def run(ctx, args) -> list[str]:
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    _validate_state(doc, existing)
    if args.streams:
        names = sorted(set(args.streams))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)

    plans = []
    for name in names:
        st = pol.settings(name)
        entry = doc["streams"].get(name, {})
        archives = _scan(ctx.data, name, st.naming)
        plans.append((name, st, entry, archives))

    out = []
    results = []
    n_rot = n_rem = n_comp = 0
    for name, st, entry, archives in plans:
        rotated, why = _decide(ctx, name, st, entry, args.force)
        kept, removed = _plan(ctx, name, st, entry, archives, rotated)
        out.append(f"{name}: rotate ({why})" if rotated else f"{name}: {why}")
        for a in kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.name}")
        for a in removed:
            out.append(f"  remove {a.name}")
        n_rot += rotated
        n_rem += len(removed)
        n_comp += sum(1 for a in kept if a.compress)
        new_entry = {}
        if rotated:
            new_entry["opened"] = dates.stamp(ctx.now)
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = {a.final: a.time for a in kept if a.time is not None}
        results.append((name, kept, removed, rotated, new_entry))
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")

    if args.dry_run:
        out.append("dry run: nothing written")
        return out

    logs = streams.logs_dir(ctx.data)
    # read everything that is to be compressed before the first write
    for name, kept, removed, rotated, _ in results:
        for a in kept:
            if a.compress:
                path = streams.log_path(ctx.data, name) if a.new else logs / a.name
                a.content = gzip.compress(path.read_bytes(), mtime=0)
        if rotated and not any(a.new and a.compress for a in kept):
            pass
    for name, kept, removed, rotated, _ in results:
        _apply(ctx, name, kept, removed, rotated)
    for name, _, _, _, new_entry in results:
        doc["streams"][name] = new_entry
    ctx.data.mkdir(parents=True, exist_ok=True)
    state_mod.save(ctx.state_path, doc)
    return out


def _apply(ctx, name, kept, removed, rotated):
    logs = streams.logs_dir(ctx.data)
    active = streams.log_path(ctx.data, name)
    for a in removed:
        (logs / a.name).unlink()
    staged = []
    counter = 0

    def temp():
        nonlocal counter
        while True:
            counter += 1
            p = logs / f".logkeep-{name}-{counter}.tmp"
            if not p.exists():
                return p

    drop = []
    for a in kept:
        if a.new:
            t = temp()
            if a.compress:
                t.write_bytes(a.content)
            else:
                os.replace(active, t)
            staged.append((t, logs / a.final))
        elif a.final != a.name:
            t = temp()
            if a.compress:
                t.write_bytes(a.content)
                drop.append(logs / a.name)
            else:
                os.replace(logs / a.name, t)
            staged.append((t, logs / a.final))
    for p in drop:
        p.unlink()
    for t, final in staged:
        os.replace(t, final)
    if rotated:
        active.write_bytes(b"")
